const raw = $json.output ?? $json.text ?? '';
const clean = String(raw).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
let classification;
try { classification = JSON.parse(clean); } catch (error) {
  classification = { domain: 'OTHER', intent: 'OTHER', risk: 'HIGH', confidence: 0, riskSignals: ['UNPARSEABLE_AGENT_OUTPUT'], missingInformation: ['Human review of classifier output'], routeTo: 'HUMAN_TRIAGE', summary: clean };
}
return [{ json: {
  requestId: $('Capture Incoming Message').item.json.requestId,
  receivedAt: $('Capture Incoming Message').item.json.receivedAt,
  rawMessage: $('Capture Incoming Message').item.json.rawMessage,
  classification
} }];

const raw = $json.output ?? $json.text ?? '';
const clean = String(raw).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
let reorg;
try { reorg = JSON.parse(clean); } catch (error) {
  reorg = { changeSummary: clean, changeTypes: [], employeeIds: [], countries: [], missingFields: ['Human review of specialist output'], warnings: ['Agent output was not valid JSON'] };
}
const classification = $('Validate Routing Envelope').item.json.classification;
const hasHRChange = (reorg.changeTypes?.length ?? 0) > 0 || classification.domain === 'HR_REORG';
const financeReasons = [];
if (reorg.budgetTransferRequired) financeReasons.push('budget transfer');
if (reorg.headcountImpact) financeReasons.push('headcount impact');
if (reorg.currentCostCenter || reorg.newCostCenter) financeReasons.push('cost-center change');
if (reorg.positionElimination) financeReasons.push('position elimination');
const legalReasons = [];
if (reorg.positionElimination) legalReasons.push('position elimination / RIF signal');
if (reorg.crossCountryTransfer) legalReasons.push('cross-country transfer');
if (reorg.roleOrTermsChange) legalReasons.push('role or employment-terms change');
if (reorg.consultationRiskSignal) legalReasons.push('local consultation-risk signal');
const missing = [...new Set([...(classification.missingInformation ?? []), ...(reorg.missingFields ?? [])])];
const needsClarification = classification.routeTo !== 'REORG_HR_AGENT' || classification.confidence < 0.75 || missing.length > 0;
const approvals = [
  { role: 'HR', required: hasHRChange, reasons: hasHRChange ? ['employee or organization change'] : [] },
  { role: 'FINANCE', required: financeReasons.length > 0, reasons: financeReasons },
  { role: 'LEGAL', required: legalReasons.length > 0, reasons: legalReasons }
];
const caseId = `REORG-POC-${Date.now()}`;
return [{ json: {
  output: {
    status: needsClarification ? 'NEEDS_CLARIFICATION' : 'AWAITING_APPROVAL',
    message: needsClarification ? 'The agents created a draft but need human clarification before approval routing.' : 'The draft case is ready for human approval. No enterprise system has been changed.',
    caseId,
    requestId: $('Validate Routing Envelope').item.json.requestId,
    classification,
    canonicalCase: reorg,
    approvalRoute: approvals,
    missingInformation: missing,
    nextStep: needsClarification ? 'Requester supplies the missing information.' : 'Collect all required human approvals against this case version.',
    demoOnly: true
  }
} }];
